double dijkstra(int start, int target, double init_speed) {
    // Since speed can vary a lot, we store best distance for each node with speed category.
    // For simplicity we treat speed as continuous and use a priority queue.
    // We'll implement a simple O(n^2) Dijkstra since n <= 1000.
    double d[MAXN];
    int visited[MAXN];
    double speed_at[MAXN];
    for (int i = 1; i <= MAXN-1; i++) {
        d[i] = DBL_MAX;
        visited[i] = 0;
        speed_at[i] = init_speed;
    }
    d[start] = 0.0;
    speed_at[start] = init_speed;

    for (int i = 1; i <= MAXN-1; i++) {
        int u = -1;
        double best = DBL_MAX;
        for (int j = 1; j <= MAXN-1; j++) {
            if (!visited[j] && d[j] < best) {
                best = d[j];
                u = j;
            }
        }
        if (u == -1) break;
        visited[u] = 1;
        for (int e = head[u]; e; e = nxt[e]) {
            int v = edges[e].v;
            int t = edges[e].t;
            int a = edges[e].a;
            double new_speed = speed_at[u] + a;
            if (new_speed <= 0) new_speed = 0.000001; // keep positive
            double cost = (double)t / speed_at[u];
            if (d[u] + cost < d[v]) {
                d[v] = d[u] + cost;
                speed_at[v] = new_speed;
            }
        }
    }
    return d[target];
}

