#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef long long ll;

typedef struct Edge {
    int to, next;
    double w;
} Edge;

typedef struct Node {
    double dist;
    int v;
    int k;
} Node;

static int cmpNode(const Node *a, const Node *b) {
    if (a->dist < b->dist) return -1;
    if (a->dist > b->dist) return 1;
    return 0;
}

typedef struct Heap {
    Node *a;
    int sz, cap;
} Heap;

static void heap_init(Heap *h, int cap) {
    h->a = (Node*)malloc(sizeof(Node) * (cap + 1));
    h->sz = 0;
    h->cap = cap;
}

static void heap_push(Heap *h, Node x) {
    if (h->sz + 1 > h->cap) {
        h->cap <<= 1;
        h->a = (Node*)realloc(h->a, sizeof(Node) * (h->cap + 1));
    }
    int i = ++h->sz;
    while (i > 1 && cmpNode(&x, &h->a[i >> 1]) < 0) {
        h->a[i] = h->a[i >> 1];
        i >>= 1;
    }
    h->a[i] = x;
}

static Node heap_pop(Heap *h) {
    Node ret = h->a[1];
    Node last = h->a[h->sz--];
    int i = 1;
    while ((i << 1) <= h->sz) {
        int c = i << 1;
        if (c + 1 <= h->sz && cmpNode(&h->a[c + 1], &h->a[c]) < 0) c++;
        if (cmpNode(&h->a[c], &last) >= 0) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(Heap *h) {
    return h->sz == 0;
}

/*
Assumed input format:
n m
v0 a b c
m lines: u v t

Per-edge perceived speed update:
s_{i+1} = a * s_i + b
(or clipped/unused c depending on original statement is unavailable)

Perceived distance of traversing an edge of time t at current speed s:
t * s

We solve shortest path in expanded state graph:
state = (vertex, edges_used)
speed after k traversals can be precomputed.
Need minimum cost from 1 to n and then from n to 1, equivalently:
min over k1,k2 of dist1[n][k1] + dist2[1][k2] with total traversals k1+k2.

Because the original statement provided here is incomplete/ambiguous, this implementation
uses the most standard interpretation compatible with the text:
- directed graph
- each edge has traversal time
- initial perceived speed given
- speed changes after each traversed edge according to parameters
- objective is minimum total perceived distance for 1->n->1

To keep computation finite, we cap number of traversals by n+m+5, which is enough for
shortest simple-path based solutions under nonnegative costs.
*/

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    double v0, a, b, c;
    if (scanf("%lf %lf %lf %lf", &v0, &a, &b, &c) != 4) return 0;

    Edge *edges = (Edge*)malloc(sizeof(Edge) * m);
    Edge *redges = (Edge*)malloc(sizeof(Edge) * m);
    int *head = (int*)malloc(sizeof(int) * (n + 1));
    int *rhead = (int*)malloc(sizeof(int) * (n + 1));
    for (int i = 1; i <= n; i++) head[i] = rhead[i] = -1;

    for (int i = 0; i < m; i++) {
        int u, v;
        double t;
        scanf("%d %d %lf", &u, &v, &t);

        edges[i].to = v;
        edges[i].w = t;
        edges[i].next = head[u];
        head[u] = i;

        redges[i].to = u;
        redges[i].w = t;
        redges[i].next = rhead[v];
        rhead[v] = i;
    }

    int K = n + m + 5;
    double *speed = (double*)malloc(sizeof(double) * (K + 1));
    speed[0] = v0;
    for (int i = 1; i <= K; i++) {
        speed[i] = a * speed[i - 1] + b;
        if (speed[i] < 0) speed[i] = 0;
        if (speed[i] > 1e100) speed[i] = 1e100;
    }

    int states = (n + 1) * (K + 1);
    double INF = 1e300;

    double *dist1 = (double*)malloc(sizeof(double) * states);
    double *dist2 = (double*)malloc(sizeof(double) * states);
    for (int i = 0; i < states; i++) dist1[i] = dist2[i] = INF;

    #define IDX(v,k) ((v) * (K + 1) + (k))

    Heap hp;
    heap_init(&hp, 1024);

    dist1[IDX(1,0)] = 0.0;
    heap_push(&hp, (Node){0.0, 1, 0});

    while (!heap_empty(&hp)) {
        Node cur = heap_pop(&hp);
        if (cur.dist != dist1[IDX(cur.v, cur.k)]) continue;
        if (cur.k == K) continue;
        for (int e = head[cur.v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            int nk = cur.k + 1;
            double nd = cur.dist + edges[e].w * speed[cur.k];
            int id = IDX(to, nk);
            if (nd < dist1[id]) {
                dist1[id] = nd;
                heap_push(&hp, (Node){nd, to, nk});
            }
        }
    }

    hp.sz = 0;
    dist2[IDX(n,0)] = 0.0;
    heap_push(&hp, (Node){0.0, n, 0});

    while (!heap_empty(&hp)) {
        Node cur = heap_pop(&hp);
        if (cur.dist != dist2[IDX(cur.v, cur.k)]) continue;
        if (cur.k == K) continue;
        for (int e = rhead[cur.v]; e != -1; e = redges[e].next) {
            int to = redges[e].to;
            int nk = cur.k + 1;
            double nd = cur.dist + redges[e].w * speed[cur.k];
            int id = IDX(to, nk);
            if (nd < dist2[id]) {
                dist2[id] = nd;
                heap_push(&hp, (Node){nd, to, nk});
            }
        }
    }

    double ans = INF;
    for (int k1 = 0; k1 <= K; k1++) {
        if (dist1[IDX(n, k1)] >= INF / 2) continue;
        for (int k2 = 0; k1 + k2 <= K; k2++) {
            if (dist2[IDX(1, k2)] >= INF / 2) continue;
            double cur = dist1[IDX(n, k1)] + dist2[IDX(1, k2)];
            if (cur < ans) ans = cur;
        }
    }

    if (ans >= INF / 2) {
        printf("-1\n");
    } else {
        printf("%.10f\n", ans);
    }

    free(edges);
    free(redges);
    free(head);
    free(rhead);
    free(speed);
    free(dist1);
    free(dist2);
    free(hp.a);

    return 0;
}

