const ld INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    vector<ld> speed(k);
    for (int i = 0; i < k; i++) {
        cin >> speed[i];
    }

    vector<vector<pair<int, ld>>> adj(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        ld w;
        cin >> u >> v >> w;
        u--; v--;
        adj[u].push_back({v, w});
    }

    // Dijkstra from (1,0) to all (v, t)
    vector<vector<ld>> dist1(n, vector<ld>(k, INF));
    using state = pair<ld, pair<int,int>>;
    priority_queue<state, vector<state>, greater<state>> pq;
    dist1[0][0] = 0;
    pq.push({0, {0, 0}});

    while (!pq.empty()) {
        auto [d, st] = pq.top(); pq.pop();
        int v = st.first, t = st.second;
        if (d > dist1[v][t] + 1e-12) continue;
        for (auto [to, w] : adj[v]) {
            int nt = (t + 1) % k;
            ld nd = d + w / speed[t];
            if (nd < dist1[to][nt] - 1e-12) {
                dist1[to][nt] = nd;
                pq.push({nd, {to, nt}});
            }
        }
    }

    // Dijkstra from each (n-1, t) to all (v, t') — we can compute backwards
    vector<vector<ld>> dist2(n, vector<ld>(k, INF));
    // Instead of running k Dijkstras, run one multi-source Dijkstra
    priority_queue<state, vector<state>, greater<state>> pq2;
    for (int t = 0; t < k; t++) {
        if (dist1[n-1][t] < INF) {
            dist2[n-1][t] = 0;
            pq2.push({0, {n-1, t}});
        }
    }

    while (!pq2.empty()) {
        auto [d, st] = pq2.top(); pq2.pop();
        int v = st.first, t = st.second;
        if (d > dist2[v][t] + 1e-12) continue;
        for (auto [to, w] : adj[v]) {
            int nt = (t + 1) % k;
            ld nd = d + w / speed[t];
            if (nd < dist2[to][nt] - 1e-12) {
                dist2[to][nt] = nd;
                pq2.push({nd, {to, nt}});
            }
        }
    }

    ld ans = INF;
    for (int t = 0; t < k; t++) {
        if (dist1[n-1][t] < INF && dist2[0][t] < INF) {
            ans = min(ans, dist1[n-1][t] + dist2[0][t]);
        }
    }

    cout << fixed << setprecision(10) << ans << "\n";

    return 0;
}

