typedef long long ll;
typedef pair<ll,int> pli;

const ll INF = 1e18;

vector<pair<int,ll>> adj[100005], radj[100005];

ll dijkstra(int src, int dst, int n, vector<pair<int,ll>> g[]) {
    vector<ll> dist(n+1, INF);
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist[dst];
}

