#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

struct Edge {
    int to;
    ll t;
};

static const long double INF = 1e100L;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    ll v0, a, b, c;
    cin >> n >> m >> v0 >> a >> b >> c;

    vector<vector<Edge>> g(n + 1), rg(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        ll t;
        cin >> u >> v >> t;
        g[u].push_back({v, t});
        rg[v].push_back({u, t});
    }

    // Speed sequence:
    // v1 = v0
    // v_{k+1} = (a * v_k + b) mod c
    //
    // Cost of traversing an edge with time t at step k is t * v_k.
    //
    // Total route cost with L edges and edge-times t1..tL:
    // sum_{k=1..L} t_k * v_k
    //
    // Since v_k depends only on step number, for shortest path with exactly L edges,
    // we need minimum possible sum of weighted edge times with position-dependent weights.
    //
    // Standard trick:
    // state = (vertex, step mod period-prefix handled by explicit expansion).
    //
    // Because v sequence is deterministic over finite states [0, c-1], it eventually
    // becomes periodic. Let:
    // prefix length = mu, cycle length = lambda.
    //
    // Build expanded graph over steps up to mu+lambda-1, and one extra layer for cycle DP.
    //
    // However costs are nonnegative, so optimal simple shortest walk between fixed endpoints
    // will never need more than n-1 edges before entering any beneficial cycle structure.
    // But because weights vary by step, revisits may help. Still, after sequence becomes periodic,
    // we can model one full period as a min-plus matrix on vertices and use shortest path in
    // layered graph + cycle relaxation.
    //
    // Simpler practical solution:
    // Build time-expanded graph for all sequence values until first repeat.
    // Let S be number of distinct states in speed sequence before repeat including first occurrence.
    // Distances[layer][vertex].
    // Since c is finite and sequence over [0,c-1], S <= c+1.
    //
    // We compute:
    // dpF[k][v] = min cost to reach v from 1 after exactly k edges
    // dpB[k][v] = min cost to reach v from n after exactly k edges in reversed graph
    //
    // Then answer is min over i,j of dpF[i][n] + dpR starting from step i+1 ...
    //
    // Actually trip is 1 -> n -> 1 continuously, so the step count continues.
    // Need:
    // bestToN[k] = min cost reaching n after k edges from 1
    // then continue from n to 1 with subsequent speeds.
    //
    // Let back[k][v] = min additional cost to go from v to 1 using exactly k edges,
    // where these k edges use speeds starting from some offset. Offset matters.
    //
    // So we need min-plus transitions by step. We can do full DP over layers:
    // forward layers from 1, and reverse DP to 1 from each layer.
    //
    // Let S = first repeat index count. Sequence values speed[1..S], where speed[S+1] repeats some earlier.
    // Since after repeat, future layer behavior repeats in terms of speed values, but absolute layer still matters.
    //
    // We construct layered graph with nodes (v, idx in unique speed-state order until repeat start+cycle-1).
    // Then run Dijkstra on product automaton with phase = position in eventual periodic sequence.
    //
    // Need path that visits n at least once and ends at 1. State additionally stores whether n has been visited.
    //
    // This is enough because edge cost depends only on current phase, and phase transition deterministic.
    //
    // Build functional graph of speed values.
    unordered_map<ll, int> pos;
    vector<ll> speed; // 0-based, speed at phase i
    ll cur = v0;
    while (!pos.count(cur)) {
        pos[cur] = (int)speed.size();
        speed.push_back(cur);
        cur = ((i128)a * cur + b) % c;
    }
    int mu = pos[cur];
    int lambda = (int)speed.size() - mu;
    int P = (int)speed.size();

    auto nextPhase = [&](int ph) -> int {
        if (ph + 1 < P) return ph + 1;
        return mu;
    };

    // Dijkstra on state (vertex, phase, seenN)
    int phases = P;
    int totalStates = (n + 1) * phases * 2;
    auto id = [&](int v, int ph, int seen) {
        return ((seen * phases + ph) * (n + 1) + v);
    };

    vector<long double> dist(totalStates, INF);
    using State = pair<long double, int>;
    priority_queue<State, vector<State>, greater<State>> pq;

    int startSeen = (1 == n ? 1 : 0);
    int sId = id(1, 0, startSeen);
    dist[sId] = 0;
    pq.push({0, sId});

    while (!pq.empty()) {
        auto [d, sid] = pq.top();
        pq.pop();
        if (d != dist[sid]) continue;

        int tmp = sid;
        int v = tmp % (n + 1);
        tmp /= (n + 1);
        int ph = tmp % phases;
        int seen = tmp / phases;

        if (v == 1 && seen) {
            cout << fixed << setprecision(15) << (double)d << '\n';
            return 0;
        }

        long double sp = (long double)speed[ph];
        int nph = nextPhase(ph);

        for (auto &e : g[v]) {
            int nseen = seen || (e.to == n);
            int nid = id(e.to, nph, nseen);
            long double nd = d + sp * (long double)e.t;
            if (nd < dist[nid]) {
                dist[nid] = nd;
                pq.push({nd, nid});
            }
        }
    }

    // If impossible
    cout << -1 << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, time;
        Edge(int to, int time) {
            this.to = to;
            this.time = time;
        }
    }

    static class State implements Comparable<State> {
        int vertex, steps;
        long dist;
        State(int vertex, int steps, long dist) {
            this.vertex = vertex;
            this.steps = steps;
            this.dist = dist;
        }
        public int compareTo(State o) {
            return Long.compare(this.dist, o.dist);
        }
    }

    static final long INF = Long.MAX_VALUE / 2;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        long A = Long.parseLong(st.nextToken());
        long B = Long.parseLong(st.nextToken());
        long C = Long.parseLong(st.nextToken());
        long D = Long.parseLong(st.nextToken());

        List<Edge>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int t = Integer.parseInt(st.nextToken());
            graph[u].add(new Edge(v, t));
        }

        // Maximum steps reasonably needed: n (simple path) or m, but we bound by 2*n for safety
        int maxSteps = 2 * n;
        long[][] distFrom1 = new long[n + 1][maxSteps + 1];
        long[][] distFromN = new long[n + 1][maxSteps + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(distFrom1[i], INF);
            Arrays.fill(distFromN[i], INF);
        }

        // Dijkstra from 1
        PriorityQueue<State> pq = new PriorityQueue<>();
        distFrom1[1][0] = 0;
        pq.offer(new State(1, 0, 0));
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int u = cur.vertex;
            int steps = cur.steps;
            if (cur.dist != distFrom1[u][steps]) continue;
            if (steps == maxSteps) continue;
            for (Edge e : graph[u]) {
                int nsteps = steps + 1;
                long w = e.time * (A + B * steps + C * steps * steps + D * steps * steps * steps);
                long nd = cur.dist + w;
                if (nd < distFrom1[e.to][nsteps]) {
                    distFrom1[e.to][nsteps] = nd;
                    pq.offer(new State(e.to, nsteps, nd));
                }
            }
        }

        // Dijkstra from n (on reversed graph)
        List<Edge>[] revGraph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) revGraph[i] = new ArrayList<>();
        for (int u = 1; u <= n; u++) {
            for (Edge e : graph[u]) {
                revGraph[e.to].add(new Edge(u, e.time));
            }
        }

        distFromN[n][0] = 0;
        pq.offer(new State(n, 0, 0));
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int u = cur.vertex;
            int steps = cur.steps;
            if (cur.dist != distFromN[u][steps]) continue;
            if (steps == maxSteps) continue;
            for (Edge e : revGraph[u]) {
                int nsteps = steps + 1;
                long w = e.time * (A + B * steps + C * steps * steps + D * steps * steps * steps);
                long nd = cur.dist + w;
                if (nd < distFromN[e.to][nsteps]) {
                    distFromN[e.to][nsteps] = nd;
                    pq.offer(new State(e.to, nsteps, nd));
                }
            }
        }

        long answer = INF;
        // combine: first part uses s1 steps, second part uses s2 steps
        for (int s1 = 1; s1 <= maxSteps; s1++) {
            if (distFrom1[n][s1] == INF) continue;
            for (int s2 = 1; s2 <= maxSteps; s2++) {
                if (distFromN[1][s2] == INF) continue;
                // total steps = s1 + s2, but second part starts with step count = s1
                // So we need to adjust the speed formula: for second part steps are offset by s1
                // But our Dijkstra from n computed cost assuming starting steps=0.
                // We must recompute the second part cost with correct step offset.
                // Since the formula is polynomial in steps, we can recompute on the fly.
                // Simpler: run Dijkstra from n with state (vertex, totalStepsSoFar) and compute cost accordingly.
                // To avoid complexity, we can run one Dijkstra from 1 and another from n but with a function that takes current total steps.
                // Actually easier: run Dijkstra on combined state (vertex, steps) from 1 to n and back using same step counter.
                // We'll do that instead.
            }
        }

        // Better approach: single Dijkstra over (vertex, steps) for round trip
        // This is done below:
        long ans = INF;
        // We'll compute minimal perceived distance from 1 to n with k steps, then from n to 1 with additional steps.
        // But we need the second leg's speed based on total steps already taken.
        // We can run Dijkstra from 1 to all states, then from n to all states with step offset.
        // To handle offset: for each state (v, s) from n, the cost to go to 1 with t more steps is distN[v][s] + cost of path from v to 1 with steps starting at s.
        // That means we need to run Dijkstra from n with state (vertex, stepsFromN) but weight function depends on (stepsFrom1 + stepsFromN).
        // We can instead run Dijkstra from 1 and from n with same step indexing and then combine by iterating over intermediate steps.

        // Simpler correct method: run two Dijkstras as above but recompute second leg cost manually:
        long[] best1 = new long[n+1];
        Arrays.fill(best1, INF);
        for (int s = 0; s <= maxSteps; s++) {
            if (distFrom1[n][s] < best1[n]) best1[n] = distFrom1[n][s];
        }

        // For second leg, we can run Dijkstra from n where the weight for an edge when we have taken totalSteps so far is computed with formula.
        // But we already have distances from n with steps starting at 0. We need to offset.
        // So we will re-run Dijkstra from n but with state including total steps from start.
        // We'll do that in a single Dijkstra from 1 to n and then continue to 1.

        // Cleanest: State (vertex, steps) and run Dijkstra from (1,0) with goal to return to (1, any steps).
        long[][] dist = new long[n+1][maxSteps+1];
        for (int i = 1; i <= n; i++) Arrays.fill(dist[i], INF);
        dist[1][0] = 0;
        pq.clear();
        pq.offer(new State(1, 0, 0));
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int u = cur.vertex;
            int steps = cur.steps;
            if (cur.dist != dist[u][steps]) continue;
            if (steps == maxSteps) continue;
            for (Edge e : graph[u]) {
                int nsteps = steps + 1;
                long w = e.time * (A + B * steps + C * (long)steps * steps + D * (long)steps * steps * steps);
                long nd = cur.dist + w;
                if (nd < dist[e.to][nsteps]) {
                    dist[e.to][nsteps] = nd;
                    pq.offer(new State(e.to, nsteps, nd));
                }
            }
        }

        for (int s = 0; s <= maxSteps; s++) {
            if (dist[1][s] > 0) ans = Math.min(ans, dist[1][s]);
        }

        System.out.println(ans);
    }
}

