        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        double v0 = sc.nextDouble(), delta = sc.nextDouble();

        List<int[]>[] adj = new List[n + 1];
        for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt(), v = sc.nextInt(), t = sc.nextInt();
            adj[u].add(new int[]{v, t});
        }

        int maxSteps = 2 * n + 5;
        double[][] dist = new double[n + 1][maxSteps];
        for (double[] row : dist) Arrays.fill(row, Double.MAX_VALUE);
        dist[1][0] = 0;

        // PQ: (cost, vertex, steps)
        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[0]));
        pq.offer(new double[]{0, 1, 0});

        double ans = Double.MAX_VALUE;

        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            double cost = cur[0];
            int u = (int) cur[1], steps = (int) cur[2];

            if (cost > dist[u][steps]) continue;

            if (u == 1 && steps > 0) {
                ans = Math.min(ans, cost);
                continue;
            }

            if (steps >= maxSteps - 1) continue;

            double speed = v0 + steps * delta;
            for (int[] e : adj[u]) {
                int v = e[0], t = e[1];
                double nc = cost + t * speed;
                if (nc < dist[v][steps + 1]) {
                    dist[v][steps + 1] = nc;
                    pq.offer(new double[]{nc, v, steps + 1});
                }
            }
        }

        System.out.printf("%.6f%n", ans);
    }
}

