public class Main {
    static class Edge {
        int to;
        double t;
        Edge(int to, double t) {
            this.to = to;
            this.t = t;
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        int m = fs.nextInt();

        double v0 = fs.nextDouble();
        double a = fs.nextDouble();
        double b = fs.nextDouble();

        List<Edge>[] g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            double t = fs.nextDouble();
            g[u].add(new Edge(v, t));
        }

        int states = 2 * n;
        int start = 1;          // phase 0, vertex 1
        int target = n + 1;     // phase 1, vertex 1
        int K = Math.max(0, 2 * n - 2);

        double INF = 1e300;
        double[] dp = new double[states + 1];
        double[] ndp = new double[states + 1];
        Arrays.fill(dp, INF);
        dp[start] = 0.0;

        double ans = INF;
        double speed = v0;

        if (n == 1) {
            // Need go from 1 to n and back to 1; since n==1, already there and back with 0 cost.
            System.out.println("0");
            return;
        }

        for (int step = 1; step <= K; step++) {
            Arrays.fill(ndp, INF);
            for (int u = 1; u <= n; u++) {
                double cur0 = dp[u];
                if (cur0 < INF / 2) {
                    for (Edge e : g[u]) {
                        int ns = (e.to == n ? n + e.to : e.to);
                        double val = cur0 + e.t * speed;
                        if (val < ndp[ns]) ndp[ns] = val;
                    }
                }
                double cur1 = dp[n + u];
                if (cur1 < INF / 2) {
                    for (Edge e : g[u]) {
                        int ns = n + e.to;
                        double val = cur1 + e.t * speed;
                        if (val < ndp[ns]) ndp[ns] = val;
                    }
                }
            }
            dp = ndp.clone();
            if (dp[target] < ans) ans = dp[target];
            speed = a * speed + b;
        }

        if (ans >= INF / 2) {
            System.out.println("-1");
        } else {
            if (Math.abs(ans - Math.rint(ans)) < 1e-9) {
                System.out.println((long) Math.rint(ans));
            } else {
                System.out.printf(Locale.US, "%.10f%n", ans);
            }
        }
    }
}
